using System.Text.RegularExpressions;using ZosyalMedya.BuildingBlocks.Domain;
namespace ZosyalMedya.Modules.Comments.Domain.Comments;
public readonly record struct CommentId(Guid Value){public static CommentId New()=>new(Guid.NewGuid());}public readonly record struct CommentAuthorId(Guid Value);public readonly record struct CommentedContentId(Guid Value);
public enum CommentStatus{Visible,Deleted,Moderated}
public sealed class Comment:AggregateRoot<CommentId>
{private static readonly Regex MentionRegex=new(@"(?<!\w)@([\p{L}\p{N}_.]{3,30})",RegexOptions.Compiled|RegexOptions.CultureInvariant);private Comment():base(default){Text=string.Empty;Mentions=[];}private Comment(CommentId id,CommentAuthorId author,CommentedContentId content,CommentId?parent,int depth,string text,DateTimeOffset now):base(id){AuthorId=author;ContentId=content;ParentId=parent;Depth=depth;Text=text;Mentions=Extract(text);Status=CommentStatus.Visible;CreatedAtUtc=now;UpdatedAtUtc=now;Version=1;}public CommentAuthorId AuthorId{get;private set;}public CommentedContentId ContentId{get;private set;}public CommentId?ParentId{get;private set;}public int Depth{get;private set;}public string Text{get;private set;}public string[]Mentions{get;private set;}public CommentStatus Status{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public static Comment Create(CommentId id,CommentAuthorId author,CommentedContentId content,CommentId?parent,int depth,string text,DateTimeOffset now){if(author.Value==Guid.Empty||content.Value==Guid.Empty)throw new DomainRuleException("comments.reference_invalid","Yazar ve içerik gereklidir.");if(depth is<0 or>5)throw new DomainRuleException("comments.depth_exceeded","Yorum derinliği en fazla 5 olabilir.");return new(id,author,content,parent,depth,Validate(text),now);}public void Edit(CommentAuthorId actor,string text,DateTimeOffset now){EnsureAuthor(actor);if(Status!=CommentStatus.Visible)throw new DomainRuleException("comments.not_editable","Silinmiş veya moderasyondaki yorum düzenlenemez.");Text=Validate(text);Mentions=Extract(Text);UpdatedAtUtc=now;Version++;}public void Delete(CommentAuthorId actor,DateTimeOffset now){EnsureAuthor(actor);if(Status!=CommentStatus.Visible)return;Status=CommentStatus.Deleted;Text=string.Empty;Mentions=[];UpdatedAtUtc=now;Version++;}public void Moderate(string reason,DateTimeOffset now){if(string.IsNullOrWhiteSpace(reason))throw new DomainRuleException("comments.moderation_reason_required","Moderasyon nedeni gereklidir.");Status=CommentStatus.Moderated;Text=string.Empty;Mentions=[];UpdatedAtUtc=now;Version++;}private void EnsureAuthor(CommentAuthorId actor){if(actor!=AuthorId)throw new DomainRuleException("comments.forbidden","Yorum yalnız yazarı tarafından değiştirilebilir.");}private static string Validate(string text){var clean=text.Trim();if(clean.Length is<1 or>2000)throw new DomainRuleException("comments.text_invalid","Yorum 1-2000 karakter olmalıdır.");return clean;}private static string[]Extract(string text)=>MentionRegex.Matches(text).Select(x=>x.Groups[1].Value).Distinct(StringComparer.OrdinalIgnoreCase).Take(20).ToArray();}
